cd /workspace/dev && python3 - <<'EOF' 2>&1 | tail -20
import sys, json, random
sys.path.insert(0,'/workspace/dev')
import gen, ref
stats = {'tx':0,'accept':0,'stale':0,'v':[0,0,0,0],'nonzero':0}
for seed in range(200):
    req = gen.gen_request(seed, sessions=2)
    for s in req['sessions']:
        r = ref.Ref(s)
        for tx in s['transactions']:
            out = r.transact(tx)
            stats['tx'] += 1
            if out['violations'] is None: stats['stale'] += 1
            else:
                if out['accepted']: stats['accept'] += 1
                else:
                    stats['nonzero'] += 1
                    for i in range(4): stats['v'][i] += 1 if out['violations'][i] else 0
print(stats)
EOF
